Given $d \geq 2$ and $\rho \in (0,1)$ sufficiently small, there exist constants $0 < a_{\rho} < b_{\rho}<1$ and $\varepsilon_{\rho} > 0$ depending only on $d$ and $\rho$ with the following property.  
\vskip0.1in
\noindent Let $E \subseteq [0,1]^d$ be any Borel set whose $s$-dimensional Hausdorff measure $\mathbb H^s(E)$ is positive for some $s > d - \varepsilon_{\rho}$. Let $\mathcal D_{\rho}(E; s)$ denote the collection of all dyadic cubes $Q$ contained in $[0,1]^d$ such that  
\begin{equation} \mathcal H_{\infty}^{s}(E \cap Q) > (1 - \rho) \ell(Q)^s,

\end{equation} 
where $\ell(Q)$ denotes the side-length of the cube $Q$. Then, 
 \begin{equation}
  \Delta(E) \supseteq 
 \bigcup \Bigl\{\ell(Q)[a_{\rho},b_{\rho}]: \; Q \in \mathcal D_{\rho}(E;s) \Bigr\}.   
 \end{equation}

\begin{enumerate}[(a)]
\item For $d \geq 2$, there exist dimensional constants $\bar{a}_d, \bar{b}_{d}, \rho_d, \bar{\varepsilon}_d \in (0,1)$ as follows. For Borel sets $E, F \subseteq [0,1]^d$ with $\min \bigl\{\mathcal H^s_{\infty}(E), \mathcal H^s_{\infty}(F) \bigr\} \geq 1 - \rho_d$, one has 
\begin{equation}  
\Delta(E, F) := \Bigl\{|x-y| : x \in E, y \in F \Bigr\} \supseteq [\bar{a}_{d}, \bar{b}_{d}], \quad \text{ provided } s \geq d - \bar{\varepsilon}_d. 
\end{equation} 
\vskip0.1in 
\item For $d \geq 2$, there exists a constant $\rho_d \in (0, 1)$ with the following property. For every $\rho \in (0, \rho_d]$, one can find $a_{\rho}, b_{\rho}, \varepsilon_{\rho}$ depending on $\rho$ such that for all Borel sets $E, F \subseteq [0,1]^d$,  
\begin{equation} 
\Delta(E, F) \supseteq [a_{\rho}, b_{\rho}], \; \text{ provided } \; \min \bigl\{\mathcal H^s_{\infty}(E), \mathcal H^s_{\infty}(F) \bigr\} \geq 1 - \rho \text{ and } s \geq d - \varepsilon. 
\end{equation}   
\noindent The parameters $a_{\rho}, b_{\rho}$ and $\varepsilon_{\rho}$ tend to 0 as $\rho \rightarrow 0$. 
\vskip0.1in
\noindent More precisely, there exists a dimensional constant $c_0 > 0$ such that for any $\kappa \in (0,1)$, the parameters $a_{\rho}, b_{\rho}, \varepsilon_{\rho}$ can be chosen to obey 
\[ a_{\rho} = \rho^{c_0}, \quad b_{\rho} = a_{\rho}^{\kappa}= \rho^{c_0 \kappa}, \quad \varepsilon_{\rho} = \frac{c_0 \rho}{\log(1/\rho)}, \]
provided $\rho$ is sufficiently small depending on $\kappa$.     
\end{enumerate}

Let $d \geq 2$. For every choice of constants $c \in (0, \frac{d-1}{4})$, $T_0 \geq 1$ and $M \geq 4$, there exists a positive constant $\delta_M$ (depending only on these quantities) as follows. 
\vskip0.1in 
\noindent Suppose that $\mu$ is a probability measure supported on a set $E \subseteq [0,1]^d$, whose $L^2$-Fourier integral obeys the growth condition  
\begin{equation}  
\mathbb F_{\mu}(T_1T_2) \leq T_1^c \mathbb F_{\mu}(T_2) \quad \text{ for all } T_1, T_2 \geq T_0.  
\end{equation} 
If there exists $\delta \in (0, \delta_M)$ and a finite sequence $\{R_j: 1 \leq j \leq J\} \subseteq (T_0, \infty)$ satisfying  
\begin{equation}  
R_{j+1} \geq \delta^{-2} R_j \quad \text{ and } \quad \sum_{j=1}^{J} \mathbb F_{\mu}(R_j) > \Bigl(1 - \frac2M \Bigr)  \mathbb F_{\mu}\bigl(\delta^{-2} R_J \bigr),
\end{equation}  
then at least one of the points $\{\delta R_j^{-1} : 1 \leq j \leq J \}$ must lie in $\Delta(E)$.

Given any $d \geq 2$, $C_0 \geq 1$ and parameters $0 < \tau_1 \leq \tau_2 < 1$, there exist constants $\varepsilon_0 \in (0, 1)$ and $J_0 \in \mathbb N$  depending on these quantities with the following property. 
\vskip0.1in 
\noindent For $s \in (d - \varepsilon_0, d)$, let $E \subseteq [0,1]^d$ be any quasi-regular Borel set, equipped with a locally uniformly $s$-dimensional probability measure $\mu$  for which (1.20) holds with the specified constant $C_0$. Then $\Delta(E)$ intersects every $J_0$-long sequence that is $(\tau_1, \tau_2)$-lacunary.  Specifically, any sequence $\{t_j : 1 \leq j \leq J_0\} \subseteq (0,1]$ with (1.21) must satisfy 
\begin{equation} \inf_{j \geq 1} \# \Bigl[ \Delta(E) \cap \bigl\{t_{1}, \ldots, t_{J_0}\bigr\} \Bigr] \geq 1.  \end{equation}  
In particular, if $\{t_j : j \geq 1\}$ is any infinite sequence that is $(\tau_1, \tau_2)$-lacunary, then every consecutive block $\{k+1, \ldots, k+J_0\}$ of $J_0$ integers contains an index $j$ with $t_j \in \Delta(E)$.

\begin{enumerate}[(a)]
\item For $d \geq 2$, there exist dimensional constants $\bar{a}_d, \bar{b}_{d}, \rho_d, \bar{\varepsilon}_d \in (0,1)$ as follows. For Borel sets $E, F \subseteq [0,1]^d$ with $\min \bigl\{\mathcal H^s_{\infty}(E), \mathcal H^s_{\infty}(F) \bigr\} \geq 1 - \rho_d$, one has 
\begin{equation}  
\Delta(E, F) := \Bigl\{|x-y| : x \in E, y \in F \Bigr\} \supseteq [\bar{a}_{d}, \bar{b}_{d}], \quad \text{ provided } s \geq d - \bar{\varepsilon}_d. 
\end{equation} 
\vskip0.1in 
\item For $d \geq 2$, there exists a constant $\rho_d \in (0, 1)$ with the following property. For every $\rho \in (0, \rho_d]$, one can find $a_{\rho}, b_{\rho}, \varepsilon_{\rho}$ depending on $\rho$ such that for all Borel sets $E, F \subseteq [0,1]^d$,  
\begin{equation} 
\Delta(E, F) \supseteq [a_{\rho}, b_{\rho}], \; \text{ provided } \; \min \bigl\{\mathcal H^s_{\infty}(E), \mathcal H^s_{\infty}(F) \bigr\} \geq 1 - \rho \text{ and } s \geq d - \varepsilon. 
\end{equation}   
\noindent The parameters $a_{\rho}, b_{\rho}$ and $\varepsilon_{\rho}$ tend to 0 as $\rho \rightarrow 0$. 
\vskip0.1in
\noindent More precisely, there exists a dimensional constant $c_0 > 0$ such that for any $\kappa \in (0,1)$, the parameters $a_{\rho}, b_{\rho}, \varepsilon_{\rho}$ can be chosen to obey 
\[ a_{\rho} = \rho^{c_0}, \quad b_{\rho} = a_{\rho}^{\kappa}= \rho^{c_0 \kappa}, \quad \varepsilon_{\rho} = \frac{c_0 \rho}{\log(1/\rho)}, \]
provided $\rho$ is sufficiently small depending on $\kappa$.     
\end{enumerate}
